// Matrix is a rectangular grid of integers.
type Matrix *matrix

type matrix struct {
	rows [][]int
	cols int
}

// New parses s as a matrix of integers. s must contain one row per line,
// with each row holding the same number of whitespace-separated integers.
func New(s string) (Matrix, error) {
	lines := strings.Split(s, "\n")
	m := &matrix{}
	for _, line := range lines {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errors.New("matrix: empty row")
		}
		row := make([]int, len(fields))
		for i, f := range fields {
			v, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[i] = v
		}
		if len(m.rows) > 0 && len(row) != m.cols {
			return nil, errors.New("matrix: uneven rows")
		}
		m.cols = len(row)
		m.rows = append(m.rows, row)
	}
	return m, nil
}

// Rows returns a copy of the matrix's rows.
func (m Matrix) Rows() [][]int {
	return m.copyRows()
}

// Cols returns a copy of the matrix's columns.
func (m Matrix) Cols() [][]int {
	cols := make([][]int, m.cols)
	for c := 0; c < m.cols; c++ {
		col := make([]int, len(m.rows))
		for r, row := range m.rows {
			col[r] = row[c]
		}
		cols[c] = col
	}
	return cols
}

