// New parses s as a matrix of integers. Each line of s is one row, and
// rows must contain the same number of whitespace-separated integers.
// It returns an error if any row is empty, rows are uneven, or a value
// is not an integer.
func New(s string) (Matrix, error) {
	m := &matrix{}
	for _, line := range strings.Split(s, "\n") {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errors.New("matrix: empty row")
		}
		row := make([]int, len(fields))
		for i, f := range fields {
			v, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[i] = v
		}
		if len(m.rows) > 0 && len(row) != m.cols {
			return nil, errors.New("matrix: uneven rows")
		}
		m.cols = len(row)
		m.rows = append(m.rows, row)
	}
	return m, nil
}

// Rows returns the matrix's rows, reading each row left-to-right while
// moving top-to-bottom. The returned data is a copy; mutating it does
// not affect the matrix.
func (m *matrix) Rows() [][]int {
	rows := make([][]int, len(m.rows))
	for i, row := range m.rows {
		rows[i] = make([]int, len(row))
		copy(rows[i], row)
	}
	return rows
}

// Cols returns the matrix's columns, reading each column top-to-bottom
// while moving from left-to-right. The returned data is a copy;
// mutating it does not affect the matrix.
func (m *matrix) Cols() [][]int {
	cols := make([][]int, m.cols)
	for c := 0; c < m.cols; c++ {
		col := make([]int, len(m.rows))
		for r, row := range m.rows {
			col[r] = row[c]
		}
		cols[c] = col
	}
	return cols
}

// Set sets the element at (row, col) to val. It reports whether the
// coordinates are within the matrix.
func (m *matrix) Set(row, col, val int) bool {
	if row < 0 || row >= len(m.rows) || col < 0 || col >= m.cols {
		return false
	}
	m.rows[row][col] = val
	return true
}
